-- 历史遗留商品：把商品总库存对齐到 SKU 库存之和（仅修正非种子商品）
UPDATE pms_product p JOIN (SELECT product_id, SUM(stock) s FROM pms_sku_stock GROUP BY product_id) t ON t.product_id = p.id
SET p.stock = t.s WHERE p.id NOT BETWEEN 2001 AND 2099 AND p.stock <> t.s;

